import React, { useEffect, useState, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import api from '../services/api';

/* ════════════════════════════════════════════════
   LANDING PAGE PUBLIQUE — EduMatch
   Inspirée du style Onyono : hero plein écran,
   navbar scrollable, cartes élégantes, animations
════════════════════════════════════════════════ */

// ── CountUp animé ──────────────────────────────
function CountUp({ target, suffix = '' }) {
  const [val, setVal] = useState(0);
  const ref = useRef(null);
  useEffect(() => {
    if (!target) return;
    const obs = new IntersectionObserver(([e]) => {
      if (!e.isIntersecting) return;
      obs.disconnect();
      const start = Date.now();
      const tick = () => {
        const p = Math.min((Date.now() - start) / 1500, 1);
        const ease = 1 - Math.pow(1 - p, 3);
        setVal(Math.floor(ease * target));
        if (p < 1) requestAnimationFrame(tick);
        else setVal(target);
      };
      requestAnimationFrame(tick);
    }, { threshold: 0.3 });
    if (ref.current) obs.observe(ref.current);
    return () => obs.disconnect();
  }, [target]);
  return <span ref={ref}>{val.toLocaleString('fr-FR')}{suffix}</span>;
}

// ── Hook scroll ────────────────────────────────
function useScrolled(threshold = 80) {
  const [scrolled, setScrolled] = useState(false);
  useEffect(() => {
    const fn = () => setScrolled(window.scrollY > threshold);
    window.addEventListener('scroll', fn);
    return () => window.removeEventListener('scroll', fn);
  }, [threshold]);
  return scrolled;
}

export default function Landing() {
  const navigate  = useNavigate();
  const scrolled  = useScrolled();
  const [stats, setStats]       = useState({ profs: 0, etudiants: 0, reservations: 0 });
  const [topProfs, setTopProfs] = useState([]);
  const [search, setSearch]     = useState('');
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    Promise.all([
      api.get('/api/admin/stats/public').catch(() => ({ data: {} })),
      api.get('/api/professeurs/').catch(() => ({ data: [] })),
    ]).then(([s, profs]) => {
      setStats({
        profs:        s.data.total_professeurs  || 0,
        etudiants:    s.data.total_etudiants    || 0,
        reservations: s.data.total_reservations || 0,
      });
      const sorted = (profs.data || [])
        .filter(p => p.statut_validation === 'validé')
        .sort((a, b) => (parseFloat(b.note_moyenne) || 0) - (parseFloat(a.note_moyenne) || 0))
        .slice(0, 4);
      setTopProfs(sorted);
    });
  }, []);

  const handleSearch = (e) => {
    e.preventDefault();
    navigate(`/profs${search ? `?q=${encodeURIComponent(search)}` : ''}`);
  };

  const MATIERES = [
    'Mathématiques', 'Physique', 'Anglais', 'Informatique',
    'Arabe', 'Français', 'Chimie', 'Comptabilité', 'SVT',
  ];

  const FEATURES = [
    { icon: '🤖', titre: 'Chatbot IA',          desc: 'Notre assistant intelligent vous guide étape par étape pour trouver le formateur idéal selon votre profil.' },
    { icon: '🎯', titre: 'Matching précis',     desc: 'Algorithme multi-critères : matière, niveau, budget, ville, disponibilités — score de compatibilité transparent.' },
    { icon: '📅', titre: 'Réservation en ligne', desc: 'Consultez les créneaux disponibles en temps réel et réservez instantanément, sans intermédiaire.' },
    { icon: '🌐', titre: 'En ligne / Présentiel', desc: 'Cours à distance avec lien Google Meet automatique, ou en face à face à domicile.' },
    { icon: '⭐', titre: 'Avis vérifiés',        desc: 'Chaque avis est laissé uniquement après un cours confirmé. Aucun avis non authentifié.' },
    { icon: '💬', titre: 'Messagerie intégrée',  desc: 'Échangez directement avec votre formateur, partagez des documents et exercices.' },
  ];

  const ETAPES = [
    { n: '01', icon: '📝', titre: 'Créez votre compte',     desc: 'Inscription gratuite en 2 minutes. Indiquez votre domaine (académique ou professionnel).' },
    { n: '02', icon: '🤖', titre: 'Décrivez votre besoin',   desc: 'Parlez à EduBot — notre IA collecte vos critères et trouve les meilleurs formateurs.' },
    { n: '03', icon: '📅', titre: 'Réservez un créneau',     desc: 'Consultez les disponibilités et confirmez votre cours en un clic.' },
    { n: '04', icon: '📚', titre: 'Commencez à apprendre !', desc: 'En ligne via Google Meet ou en présentiel. Notez votre formateur après le cours.' },
  ];

  return (
    <div style={{ minHeight: '100vh', background: '#0a0a0a', fontFamily: "'Inter', sans-serif", color: '#fff' }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=Syne:wght@700;800&display=swap');
        * { box-sizing: border-box; margin: 0; padding: 0; }
        html { scroll-behavior: smooth; }

        @keyframes fadeUp {
          from { opacity: 0; transform: translateY(30px); }
          to   { opacity: 1; transform: translateY(0); }
        }
        @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
        @keyframes float  { 0%,100%{transform:translateY(0)} 50%{transform:translateY(-8px)} }
        @keyframes gradMove {
          0%   { background-position: 0% 50%; }
          50%  { background-position: 100% 50%; }
          100% { background-position: 0% 50%; }
        }

        .anim-1 { animation: fadeUp .8s ease both; }
        .anim-2 { animation: fadeUp .8s .15s ease both; }
        .anim-3 { animation: fadeUp .8s .3s ease both; }
        .anim-4 { animation: fadeUp .8s .45s ease both; }

        .card-hover { transition: all .3s cubic-bezier(.4,0,.2,1); }
        .card-hover:hover { transform: translateY(-6px); }

        .btn-primary {
          padding: 14px 32px;
          background: #fff;
          color: #000;
          border: none;
          border-radius: 0;
          cursor: pointer;
          font-size: .8rem;
          font-weight: 600;
          letter-spacing: .1em;
          text-transform: uppercase;
          transition: all .4s;
        }
        .btn-primary:hover { background: #6c63ff; color: #fff; }

        .btn-outline {
          padding: 14px 32px;
          background: transparent;
          color: #fff;
          border: 1px solid rgba(255,255,255,0.5);
          border-radius: 0;
          cursor: pointer;
          font-size: .8rem;
          font-weight: 600;
          letter-spacing: .1em;
          text-transform: uppercase;
          transition: all .4s;
        }
        .btn-outline:hover { background: #fff; color: #000; }

        .nav-link {
          font-size: .7rem;
          letter-spacing: .15em;
          text-transform: uppercase;
          text-decoration: none;
          transition: opacity .2s;
          cursor: pointer;
          background: none;
          border: none;
        }
        .nav-link:hover { opacity: .5; }

        .prof-card {
          background: #111;
          border: 1px solid #222;
          transition: all .35s;
          cursor: pointer;
          overflow: hidden;
        }
        .prof-card:hover { border-color: #6c63ff; transform: translateY(-4px); }

        .tag {
          display: inline-block;
          padding: 3px 10px;
          font-size: .65rem;
          letter-spacing: .08em;
          text-transform: uppercase;
          border: 1px solid #333;
          color: #999;
          transition: all .2s;
        }
        .tag:hover { border-color: #6c63ff; color: #6c63ff; cursor: pointer; }

        input::placeholder { color: rgba(255,255,255,0.3); }
        input:focus { outline: none; }

        ::-webkit-scrollbar { width: 4px; }
        ::-webkit-scrollbar-track { background: #111; }
        ::-webkit-scrollbar-thumb { background: #333; }
      `}</style>

      {/* ════ NAVBAR ════ */}
      <nav style={{
        position: 'fixed', top: 0, left: 0, right: 0, zIndex: 100,
        padding: scrolled ? '16px 40px' : '28px 40px',
        background: scrolled ? 'rgba(10,10,10,0.95)' : 'transparent',
        backdropFilter: scrolled ? 'blur(12px)' : 'none',
        borderBottom: scrolled ? '1px solid #1a1a1a' : 'none',
        transition: 'all .4s',
        display: 'flex', alignItems: 'center', justifyContent: 'space-between',
      }}>
        {/* Logo */}
        <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
          <div style={{ width: 34, height: 34, background: 'linear-gradient(135deg,#6c63ff,#ff6584)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1rem' }}>🎓</div>
          <span style={{ fontFamily: 'Syne', fontWeight: 800, fontSize: '1.1rem', letterSpacing: '.05em', color: '#fff' }}>EduMatch</span>
        </div>

        {/* Nav links */}
        <div style={{ display: 'flex', gap: 36, alignItems: 'center' }}>
          <button className="nav-link" style={{ color: '#fff' }} onClick={() => document.getElementById('profs')?.scrollIntoView({ behavior: 'smooth' })}>
            Formateurs
          </button>
          <button className="nav-link" style={{ color: '#fff' }} onClick={() => document.getElementById('features')?.scrollIntoView({ behavior: 'smooth' })}>
            Fonctionnalités
          </button>
          <button className="nav-link" style={{ color: '#fff' }} onClick={() => document.getElementById('etapes')?.scrollIntoView({ behavior: 'smooth' })}>
            Comment ça marche
          </button>
        </div>

        {/* Auth buttons */}
        <div style={{ display: 'flex', gap: 12, alignItems: 'center' }}>
          <button className="nav-link" style={{ color: '#fff' }} onClick={() => navigate('/login')}>
            Connexion
          </button>
          <button
            onClick={() => navigate('/register')}
            style={{ padding: '9px 20px', background: '#fff', color: '#000', border: 'none', cursor: 'pointer', fontSize: '.7rem', fontWeight: 700, letterSpacing: '.1em', textTransform: 'uppercase', transition: 'all .3s' }}
            onMouseEnter={e => { e.currentTarget.style.background = '#6c63ff'; e.currentTarget.style.color = '#fff'; }}
            onMouseLeave={e => { e.currentTarget.style.background = '#fff'; e.currentTarget.style.color = '#000'; }}
          >
            S'inscrire
          </button>
        </div>
      </nav>

      {/* ════ HERO — plein écran avec image de fond ════ */}
      <section style={{ position: 'relative', height: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', overflow: 'hidden' }}>
        {/* Image de fond */}
        <div style={{ position: 'absolute', inset: 0 }}>
          <img
            src="https://images.unsplash.com/photo-1522202176988-66273c2fd55f?auto=format&fit=crop&w=1920&q=80"
            alt=""
            style={{ width: '100%', height: '100%', objectFit: 'cover', opacity: 0.25 }}
          />
          {/* Overlay gradient */}
          <div style={{ position: 'absolute', inset: 0, background: 'linear-gradient(to bottom, rgba(10,10,10,0.3) 0%, rgba(10,10,10,0.7) 60%, #0a0a0a 100%)' }} />
        </div>

        {/* Contenu hero */}
        <div style={{ position: 'relative', zIndex: 1, textAlign: 'center', padding: '0 24px', maxWidth: 900, width: '100%' }}>
          <div className="anim-1" style={{ fontSize: '.7rem', letterSpacing: '.4em', textTransform: 'uppercase', color: 'rgba(255,255,255,0.5)', marginBottom: 28 }}>
            Plateforme de formation en Tunisie
          </div>

          <h1 className="anim-2" style={{ fontFamily: 'Syne', fontSize: 'clamp(2.5rem, 6vw, 5rem)', fontWeight: 800, lineHeight: 1.05, marginBottom: 28, letterSpacing: '-.02em' }}>
            Apprenez sans<br />
            <span style={{ background: 'linear-gradient(90deg, #fff 0%, rgba(255,255,255,0.5) 100%)', WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent', backgroundClip: 'text' }}>
              compromis.
            </span>
          </h1>

          <p className="anim-3" style={{ fontSize: '1rem', color: 'rgba(255,255,255,0.55)', maxWidth: 520, margin: '0 auto 48px', lineHeight: 1.75, fontWeight: 300 }}>
            Cours académiques, formations professionnelles — trouvez le formateur idéal grâce à l'intelligence artificielle.
          </p>

          {/* Barre de recherche style Onyono */}
          <form className="anim-4" onSubmit={handleSearch}
            style={{ display: 'flex', maxWidth: 560, margin: '0 auto 24px', border: '1px solid rgba(255,255,255,0.15)', background: 'rgba(255,255,255,0.05)', backdropFilter: 'blur(10px)' }}
          >
            <input
              value={search}
              onChange={e => setSearch(e.target.value)}
              placeholder="Matière ou domaine..."
              style={{ flex: 1, background: 'none', border: 'none', padding: '16px 20px', color: '#fff', fontSize: '.9rem' }}
            />
            <button type="submit"
              style={{ padding: '16px 24px', background: '#fff', color: '#000', border: 'none', cursor: 'pointer', fontSize: '.7rem', fontWeight: 700, letterSpacing: '.12em', textTransform: 'uppercase', transition: 'background .3s', whiteSpace: 'nowrap' }}
              onMouseEnter={e => e.currentTarget.style.background = '#6c63ff'}
              onMouseLeave={e => e.currentTarget.style.background = '#fff'}
            >
              Rechercher
            </button>
          </form>

          {/* Matières rapides */}
          <div className="anim-4" style={{ display: 'flex', flexWrap: 'wrap', gap: 8, justifyContent: 'center' }}>
            {MATIERES.map(m => (
              <button key={m} className="tag"
                onClick={() => navigate(`/profs?q=${encodeURIComponent(m)}`)}
              >
                {m}
              </button>
            ))}
          </div>
        </div>

        {/* Scroll indicator */}
        <div style={{ position: 'absolute', bottom: 32, left: '50%', transform: 'translateX(-50%)', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 6, animation: 'float 2s infinite', opacity: .4 }}>
          <div style={{ width: 1, height: 40, background: 'rgba(255,255,255,0.4)' }} />
          <span style={{ fontSize: '.6rem', letterSpacing: '.2em', textTransform: 'uppercase', color: 'rgba(255,255,255,0.4)' }}>Défiler</span>
        </div>
      </section>

      {/* ════ STATS ════ */}
      <section style={{ padding: '64px 40px', borderTop: '1px solid #1a1a1a', borderBottom: '1px solid #1a1a1a' }}>
        <div style={{ maxWidth: 900, margin: '0 auto', display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(180px, 1fr))', gap: 0 }}>
          {[
            { val: stats.profs,        suf: '+', label: 'Formateurs certifiés',  sub: 'Académique & professionnel' },
            { val: stats.etudiants,    suf: '+', label: 'Apprenants inscrits',    sub: 'Élèves, étudiants, pros' },
            { val: stats.reservations, suf: '',  label: 'Cours réservés',         sub: 'En ligne & présentiel' },
            { val: 10,                 suf: '+', label: 'Villes en Tunisie',       sub: 'Tunis, Sfax, Sousse...' },
          ].map((s, i) => (
            <div key={i} style={{ textAlign: 'center', padding: '32px 20px', borderRight: i < 3 ? '1px solid #1a1a1a' : 'none' }}>
              <div style={{ fontFamily: 'Syne', fontSize: '3rem', fontWeight: 800, color: '#fff', lineHeight: 1 }}>
                <CountUp target={s.val} suffix={s.suf} />
              </div>
              <div style={{ fontSize: '.82rem', color: '#fff', marginTop: 10, fontWeight: 500 }}>{s.label}</div>
              <div style={{ fontSize: '.7rem', color: '#555', marginTop: 4 }}>{s.sub}</div>
            </div>
          ))}
        </div>
      </section>

      {/* ════ TOP FORMATEURS ════ */}
      {topProfs.length > 0 && (
        <section id="profs" style={{ padding: '80px 40px' }}>
          <div style={{ maxWidth: 1200, margin: '0 auto' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end', marginBottom: 48 }}>
              <div>
                <p style={{ fontSize: '.68rem', letterSpacing: '.25em', textTransform: 'uppercase', color: '#555', marginBottom: 10 }}>Sélectionnés pour leur excellence</p>
                <h2 style={{ fontFamily: 'Syne', fontSize: '2rem', fontWeight: 800, lineHeight: 1.1 }}>Nos Formateurs</h2>
              </div>
              <button onClick={() => navigate('/login')}
                style={{ fontSize: '.7rem', letterSpacing: '.12em', textTransform: 'uppercase', color: '#fff', background: 'none', border: 'none', cursor: 'pointer', borderBottom: '1px solid #fff', paddingBottom: 2, display: 'flex', alignItems: 'center', gap: 6, transition: 'opacity .2s' }}
                onMouseEnter={e => e.currentTarget.style.opacity = '.5'}
                onMouseLeave={e => e.currentTarget.style.opacity = '1'}
              >
                Voir tout →
              </button>
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(260px, 1fr))', gap: 1, background: '#1a1a1a' }}>
              {topProfs.map(p => {
                const nom   = `${p.user_prenom || ''} ${p.user_nom || ''}`.trim();
                const mats  = p.tarifs_matieres ? [...new Set(p.tarifs_matieres.map(t => t.nom_matiere))].slice(0, 2) : [];
                const note  = parseFloat(p.note_moyenne || 0);
                const tarifs = [p.tarif_en_ligne, p.tarif_presentiel].filter(v => v && parseFloat(v) > 0).map(Number);
                const tmin   = tarifs.length ? Math.min(...tarifs) : null;

                return (
                  <div key={p.id} className="prof-card" onClick={() => navigate('/login')} style={{ background: '#0a0a0a', padding: 28 }}>
                    {/* Photo */}
                    <div style={{ width: 52, height: 52, borderRadius: '50%', overflow: 'hidden', background: '#1a1a1a', marginBottom: 20, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.4rem', flexShrink: 0 }}>
                      {p.photo_url
                        ? <img src={`http://localhost:8001${p.photo_url}`} alt="" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                        : '👨‍🏫'}
                    </div>

                    {/* Nom + ville */}
                    <div style={{ fontFamily: 'Syne', fontSize: '.9rem', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '.05em', marginBottom: 4 }}>{nom}</div>
                    {p.ville && <div style={{ fontSize: '.7rem', color: '#555', marginBottom: 16 }}>{p.ville}</div>}

                    {/* Matières */}
                    <div style={{ display: 'flex', flexWrap: 'wrap', gap: 5, marginBottom: 20 }}>
                      {mats.map(m => (
                        <span key={m} style={{ fontSize: '.62rem', padding: '2px 8px', border: '1px solid #2a2a2a', color: '#888', textTransform: 'uppercase', letterSpacing: '.06em' }}>{m}</span>
                      ))}
                    </div>

                    {/* Note + prix */}
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                      <div style={{ display: 'flex', gap: 2 }}>
                        {[1,2,3,4,5].map(i => (
                          <span key={i} style={{ color: i <= Math.round(note) ? '#f59e0b' : '#222', fontSize: '.75rem' }}>★</span>
                        ))}
                        <span style={{ fontSize: '.65rem', color: '#555', marginLeft: 5 }}>{note > 0 ? note.toFixed(1) : 'Nouveau'}</span>
                      </div>
                      {tmin && <span style={{ fontSize: '.75rem', color: '#fff', fontWeight: 600 }}>dès {tmin} DT/h</span>}
                    </div>
                  </div>
                );
              })}
            </div>

            <div style={{ textAlign: 'center', marginTop: 40 }}>
              <button className="btn-outline" onClick={() => navigate('/login')}>
                Voir tous les formateurs
              </button>
            </div>
          </div>
        </section>
      )}

      {/* ════ FEATURES ════ */}
      <section id="features" style={{ padding: '80px 40px', borderTop: '1px solid #1a1a1a' }}>
        <div style={{ maxWidth: 1200, margin: '0 auto' }}>
          <div style={{ marginBottom: 56 }}>
            <p style={{ fontSize: '.68rem', letterSpacing: '.25em', textTransform: 'uppercase', color: '#555', marginBottom: 10 }}>Conçu pour vous</p>
            <h2 style={{ fontFamily: 'Syne', fontSize: '2rem', fontWeight: 800, maxWidth: 400 }}>Pourquoi choisir EduMatch ?</h2>
          </div>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(340px, 1fr))', gap: 1, background: '#1a1a1a' }}>
            {FEATURES.map((f, i) => (
              <div key={i} style={{ background: '#0a0a0a', padding: 36, transition: 'background .2s', cursor: 'default' }}
                onMouseEnter={e => e.currentTarget.style.background = '#111'}
                onMouseLeave={e => e.currentTarget.style.background = '#0a0a0a'}
              >
                <div style={{ fontSize: '1.6rem', marginBottom: 18 }}>{f.icon}</div>
                <h3 style={{ fontFamily: 'Syne', fontSize: '.9rem', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '.08em', marginBottom: 12 }}>{f.titre}</h3>
                <p style={{ fontSize: '.82rem', color: '#666', lineHeight: 1.75, fontWeight: 300 }}>{f.desc}</p>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* ════ COMMENT ÇA MARCHE ════ */}
      <section id="etapes" style={{ padding: '80px 40px', borderTop: '1px solid #1a1a1a' }}>
        <div style={{ maxWidth: 1100, margin: '0 auto' }}>
          <div style={{ textAlign: 'center', marginBottom: 56 }}>
            <p style={{ fontSize: '.68rem', letterSpacing: '.25em', textTransform: 'uppercase', color: '#555', marginBottom: 10 }}>Simple et rapide</p>
            <h2 style={{ fontFamily: 'Syne', fontSize: '2rem', fontWeight: 800 }}>Comment ça marche ?</h2>
          </div>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))', gap: 0 }}>
            {ETAPES.map((s, i) => (
              <div key={i} style={{ padding: '40px 28px', borderRight: i < 3 ? '1px solid #1a1a1a' : 'none', position: 'relative' }}>
                {/* Numéro */}
                <div style={{ fontSize: '4rem', fontFamily: 'Syne', fontWeight: 800, color: '#1a1a1a', lineHeight: 1, marginBottom: 24 }}>{s.n}</div>
                <div style={{ fontSize: '1.4rem', marginBottom: 14 }}>{s.icon}</div>
                <h3 style={{ fontFamily: 'Syne', fontSize: '.85rem', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '.08em', marginBottom: 12, color: '#fff' }}>{s.titre}</h3>
                <p style={{ fontSize: '.78rem', color: '#666', lineHeight: 1.7, fontWeight: 300 }}>{s.desc}</p>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* ════ DOMAINES ════ */}
      <section style={{ padding: '80px 40px', borderTop: '1px solid #1a1a1a', background: '#050505' }}>
        <div style={{ maxWidth: 1000, margin: '0 auto', textAlign: 'center' }}>
          <p style={{ fontSize: '.68rem', letterSpacing: '.25em', textTransform: 'uppercase', color: '#555', marginBottom: 10 }}>Académique & Professionnel</p>
          <h2 style={{ fontFamily: 'Syne', fontSize: '2rem', fontWeight: 800, marginBottom: 48 }}>Tous les domaines</h2>
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 10, justifyContent: 'center' }}>
            {[
              '📐 Mathématiques', '⚗️ Physique-Chimie', '🌍 Anglais / Français',
              '💻 Informatique',  '📖 Arabe / Philo',   '🧬 SVT / Biologie',
              '💰 Comptabilité',  '📊 Marketing',        '🎨 Design',
              '🔧 Électronique',  '⚖️ Droit',            '🌐 Langues étrangères',
            ].map(d => (
              <button key={d} className="tag" onClick={() => navigate('/login')}
                style={{ fontSize: '.72rem', padding: '10px 18px' }}
              >
                {d}
              </button>
            ))}
          </div>
        </div>
      </section>

      {/* ════ CTA ════ */}
      <section style={{ padding: '100px 40px', textAlign: 'center', position: 'relative', overflow: 'hidden' }}>
        <div style={{ position: 'absolute', inset: 0, background: 'radial-gradient(ellipse at center, rgba(108,99,255,0.12) 0%, transparent 70%)' }} />
        <div style={{ position: 'relative', zIndex: 1 }}>
          <p style={{ fontSize: '.68rem', letterSpacing: '.35em', textTransform: 'uppercase', color: '#555', marginBottom: 20 }}>Commencez aujourd'hui</p>
          <h2 style={{ fontFamily: 'Syne', fontSize: 'clamp(2rem, 5vw, 3.5rem)', fontWeight: 800, lineHeight: 1.05, marginBottom: 48 }}>
            Prêt à apprendre<br />sans compromis ?
          </h2>
          <div style={{ display: 'flex', gap: 14, justifyContent: 'center', flexWrap: 'wrap' }}>
            <button className="btn-primary" onClick={() => navigate('/register')}>
              🎓 Je suis apprenant
            </button>
            <button className="btn-outline" onClick={() => navigate('/register?role=professeur')}>
              👨‍🏫 Je suis formateur
            </button>
          </div>
        </div>
      </section>

      {/* ════ FOOTER style Onyono ════ */}
      <footer style={{ borderTop: '1px solid #1a1a1a', padding: '48px 40px' }}>
        <div style={{ maxWidth: 1200, margin: '0 auto', display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: 40, marginBottom: 40 }}>
          {/* Logo + tagline */}
          <div>
            <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 16 }}>
              <div style={{ width: 28, height: 28, background: 'linear-gradient(135deg,#6c63ff,#ff6584)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '.85rem' }}>🎓</div>
              <span style={{ fontFamily: 'Syne', fontWeight: 800, fontSize: '1rem' }}>EduMatch</span>
            </div>
            <p style={{ fontSize: '.75rem', color: '#444', lineHeight: 1.7, fontStyle: 'italic', fontWeight: 300 }}>
              Redéfinir l'apprentissage par l'intelligence artificielle et la mise en relation humaine.
            </p>
          </div>

          {/* Liens */}
          <div style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
            {['Trouver un formateur', 'Devenir formateur', 'À propos', 'Contact'].map(l => (
              <button key={l} onClick={() => navigate('/login')}
                style={{ fontSize: '.7rem', letterSpacing: '.12em', textTransform: 'uppercase', color: '#555', background: 'none', border: 'none', cursor: 'pointer', textAlign: 'left', transition: 'color .2s' }}
                onMouseEnter={e => e.currentTarget.style.color = '#fff'}
                onMouseLeave={e => e.currentTarget.style.color = '#555'}
              >
                {l}
              </button>
            ))}
          </div>

          {/* Newsletter */}
          <div>
            <p style={{ fontSize: '.65rem', letterSpacing: '.15em', textTransform: 'uppercase', color: '#555', marginBottom: 16 }}>Newsletter</p>
            <div style={{ display: 'flex', borderBottom: '1px solid #333', paddingBottom: 8 }}>
              <input
                type="email"
                placeholder="VOTRE EMAIL"
                style={{ flex: 1, background: 'none', border: 'none', color: '#fff', fontSize: '.7rem', letterSpacing: '.08em' }}
              />
              <button style={{ fontSize: '.65rem', letterSpacing: '.1em', textTransform: 'uppercase', color: '#fff', background: 'none', border: 'none', cursor: 'pointer', fontWeight: 700 }}>
                OK
              </button>
            </div>
          </div>
        </div>

        <div style={{ borderTop: '1px solid #1a1a1a', paddingTop: 24, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <p style={{ fontSize: '.65rem', color: '#444', letterSpacing: '.05em' }}>
            © {new Date().getFullYear()} EduMatch — Projet PFE · ISIMS Sfax
          </p>
          <p style={{ fontSize: '.65rem', color: '#333', letterSpacing: '.05em' }}>
            Académique & Professionnel · Tunisie
          </p>
        </div>
      </footer>
    </div>
  );
}
